import{z as n,x as d,o as l,c as p,q as B,j as A,D as e,d as i,s as o,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"最优货币政策","description":"","frontmatter":{"title":"最优货币政策","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/optimal-nk-policy.md","filePath":"econ/optimal-nk-policy.md","lastUpdated":1791063341000}'),s={name:"econ/optimal-nk-policy.md"};function m(C,a,F,D,_,c){const t=d("Mermaid");return l(),p("div",null,[a[2]||(a[2]=B('<h1 id="最优货币政策" tabindex="-1">最优货币政策 <a class="header-anchor" href="#最优货币政策" aria-label="Permalink to &quot;最优货币政策&quot;">​</a></h1><div class="epigraph"><p>二次损失把通胀与缺口的权衡写成一个目标；最优不是「两个工具」，而是一条把二者锁在一起的目标制规则。</p><footer>—— Woodford, Interest and Prices, 2003；Clarida, Galí and Gertler, The Science of Monetary Policy, JEL 1999</footer></div><p><a href="/econ/divine-coincidence">上一课</a>说明：仅价格粘性、无成本推动时，稳通胀即稳福利缺口；巧合破裂后必须权衡。本课的缺口是把权衡写成 Ramsey 问题：最小化 Woodford 二次损失，得到承诺下的目标制规则。通胀目标制下一课才把它收成可操作的制度；本课先给最优条件，不谈走廊操作。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>损失</p> \\[\\mathbb{E}_0\\sum_{t=0}^{\\infty}\\beta^t\\bigl(\\pi_t^2+\\lambda_y\\tilde{y}_t^2\\bigr) \\]<p>在巧合下被 NKPC 锁死，最优是 \\(\\pi=0\\)（或钉 \\(\\pi^*\\)）。有 \\(u_t\\) 或工资粘性时，两项真正分叉。缺口不是再解释巧合是否存在，而是：承诺与权变各给出怎样的一阶条件。Clarida–Galí–Gertler（CGG）把最优写成对通胀与缺口的线性反馈直觉；Woodford 强调承诺下的历史依赖——过去的缺口仍进入今天的目标。权变课已经对比过两条路径；本课把最优条件钉在 NK 约束上。</p><p><span class="marginnote">「历史依赖」翻译成大白话：承诺下的最优政策是一本记账的账本——今天多容忍一分通胀，规则就要求明天把账还回来（一段低于目标的通胀）。权变者每期撕掉重写，没有账本，公众因此不敢信。</span></p><p><span class="marginnote">\\(\\lambda_y\\) 来自福利近似，随 \\(\\kappa\\) 与消费替代弹性变，不是「委员会更关心失业」的任意权重。把 \\(\\lambda_y\\) 当政治偏好，会取消 Woodford 的微观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约束是 NKPC（可加混合项、工资菲利普斯）与动态 IS。工具是 \\(i\\)，但最优常先写成<strong>目标制</strong>：\\(\\pi\\) 与 \\(\\tilde{y}\\) 的线性组合为零，再倒求出支撑它的 \\(i\\)。承诺：央行像 Ramsey 计划者，对未来约束自己，一阶条件含滞后乘数——通胀在冲击后超调回来。权变：每期重新优化，没有这笔历史账，稳定偏误与更差的权衡再现。</p>',11)),(l(),A(r,null,{default:e(()=>[o(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOSS%5B%22%E4%BA%8C%E6%AC%A1%E6%8D%9F%E5%A4%B1%20%CF%80%C2%B2%20%2B%20%CE%BBy%20%E1%BB%B9%C2%B2%22%5D%20--%3E%20RAM%5B%22Ramsey%20%2F%20%E6%89%BF%E8%AF%BA%22%5D%0A%20%20LOSS%20--%3E%20DIS%5B%22%E6%9D%83%E5%8F%98%22%5D%0A%20%20RAM%20--%3E%20TR%5B%22%E7%9B%AE%E6%A0%87%E5%88%B6%E8%A7%84%E5%88%99%22%5D%0A%20%20NKPC%5B%22NKPC%20%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20RAM%0A%20%20NKPC%20--%3E%20DIS%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"泰勒规则是实现目标制的一种工具规则，系数要对准最优条件，不是 1993 年拟合的再贴。泰勒原理（\\(\\phi_\\pi\\gt 1\\)）仍是确定性的最低要求；最优通常更激进或含惯性。",-1)),a[4]||(a[4]=E("h3",{id:"巧合破裂才有真正的两项",tabindex:"-1"},[i("巧合破裂才有真正的两项 "),E("a",{class:"header-anchor",href:"#巧合破裂才有真正的两项","aria-label":'Permalink to "巧合破裂才有真正的两项"'},"​")],-1)),a[5]||(a[5]=E("p",null,"无 \\(u_t\\) 时目标制退化为「永远钉通胀」，\\(\\tilde{y}\\) 项是冗余的充分统计。有成本推动时，允许通胀暂时偏离以保缺口，权重由 \\(\\lambda_y\\) 与 NKPC 斜率给出。不要把泰勒规则里同时出现的 \\(\\phi_\\pi\\)、\\(\\phi_y\\) 当成两个独立目标已经最优。",-1)),a[6]||(a[6]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=E("p",null,"成本推动到来：承诺把部分冲击摊到未来一段偏低的 \\(\\pi\\)，今天的双偏离更小。权变不肯承认未来要「还账」，今天就打得更死或更松，预期更差。神圣巧合成立时，这笔账是空的。下限上 \\(i\\) 卡住，最优改成对未来路径的承诺——非常规课已经预告，本课在正利率区把一阶条件写完。",-1)),(l(),A(r,null,{default:e(()=>[o(t,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%88%90%E6%9C%AC%E6%8E%A8%E5%8A%A8%E5%86%B2%E5%87%BB%EF%BC%9A%E9%80%9A%E8%83%80%E8%A2%AB%E9%A1%B6%E4%B8%8A%E5%8E%BB%22%5D%20--%3E%20Q%7B%22%E5%A4%AE%E8%A1%8C%E6%8C%89%E6%89%BF%E8%AF%BA%E8%A1%8C%E4%BA%8B%E8%BF%98%E6%98%AF%E6%9D%83%E5%8F%98%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%89%BF%E8%AF%BA%EF%BC%9A%E5%85%91%E7%8E%B0%E6%9C%AA%E6%9D%A5%E7%9A%84%E8%B4%A6%22%7C%20P1%5B%22%E4%BB%8A%E5%A4%A9%E5%85%81%E8%AE%B8%E9%80%9A%E8%83%80%E5%B0%8F%E5%B9%85%E5%81%8F%E7%A6%BB%E7%9B%AE%E6%A0%87%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E9%9A%8F%E5%90%8E%E6%95%B0%E6%9C%9F%E6%8A%8A%20%CF%80%20%E5%8E%8B%E5%88%B0%E7%9B%AE%E6%A0%87%E4%B9%8B%E4%B8%8B%E8%BF%98%E8%B4%A6%22%5D%0A%20%20P2%20--%3E%20P3%5B%22%E5%81%8F%E7%A6%BB%E8%A2%AB%E6%91%8A%E5%B9%B3%EF%BC%8C%E6%80%BB%E6%8D%9F%E5%A4%B1%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9D%83%E5%8F%98%EF%BC%9A%E6%AF%8F%E6%9C%9F%E9%87%8D%E6%96%B0%E4%BC%98%E5%8C%96%22%7C%20D1%5B%22%E4%BB%8A%E5%A4%A9%E5%B0%B1%E6%8A%8A%E9%80%9A%E8%83%80%E6%89%93%E5%9B%9E%E7%9B%AE%E6%A0%87%22%5D%0A%20%20D1%20--%3E%20D2%5B%22%E4%B8%8D%E8%AE%A4%E5%8E%86%E5%8F%B2%E8%B4%A6%EF%BC%8C%E9%A2%84%E6%9C%9F%E5%8F%AF%E4%BF%A1%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20D2%20--%3E%20D3%5B%22%E6%9D%83%E8%A1%A1%E5%8F%98%E5%B7%AE%EF%BC%8C%E6%80%BB%E6%8D%9F%E5%A4%B1%E6%9B%B4%E5%A4%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=B('<p><span class="marginnote">直觉类比：承诺像分期还债——成本推动的「账」摊到未来好几个季度慢慢还，每期还得少；权变像每次到期都重新谈条件，债主只好要更高的补偿。损失是平方型的，大偏离惩罚特别重，所以把偏离摊平比忽高忽低更省。</span></p><p>工资粘性使损失里还应有工资通胀项（EHL）。本课基准仍用价格 \\(\\pi\\) 与 \\(\\tilde{y}\\)；对象一变，目标制的组合系数变。金融加速器把净值加进状态，最优会含金融变量——不在本课展开。</p><p>工具规则与目标规则不要焊死：许多 \\(i\\) 路径可以暂时支撑同一组 \\((\\pi,\\tilde{y})\\)，确定性要求对名义变量反应足够。最优课给出的是目标空间里的一阶条件；下一课的 IT 把它说成公开的 \\(\\pi^*\\)。把 1993 年泰勒系数当成已经最优，会取消 \\(\\lambda_y\\) 与 NKPC 斜率的微观。</p><p><span class="marginnote">「灵活通胀目标」是下一课的制度语言：中期钉 \\(\\pi^*\\)，短期允许权衡。本课的目标制规则是它的优化原型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计 \\(\\lambda_y\\)，不把最优写成某一次加息的对错。量化栏没有宏观 Ramsey。操作上如何把 \\(i\\) 钉在走廊里，是再后一课。开放汇率错位会加进损失，蒙代尔再打开。</p><p>二次近似在大冲击与有效下限上会坏：损失非二次，最优承诺的形状要重算。本课在稳态附近把一阶条件钉住，以便 IT 课有一个可沟通的原型。时间不一致课已经说明权变有稳定偏误；本课只把偏误对照成「缺少历史依赖的那条一阶条件」。</p><p>后课默认：NK 最优政策首先是目标制条件，工具规则是实现；承诺含历史依赖。下一课：通胀目标制如何把这条条件变成公开的制度。</p><p><span class="marginnote">常见误区：把泰勒规则里同时出现的通胀系数与产出系数，读成「央行有两个独立目标」。它们只是实现同一目标制条件的工具路径；真正的权衡写在损失函数的 \\(\\lambda_y\\) 里，不是规则里有两个各自为政的旋钮。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>巧合课给出何时必须权衡；本课给出二次损失下的一阶条件。</li><li>承诺：目标制加历史依赖；权变没有这笔账。</li><li>工具是 \\(i\\)，最优先写成 \\(\\pi\\) 与 \\(\\tilde{y}\\) 的组合。</li><li>\\(\\lambda_y\\) 来自福利近似，不是任意政治权重。</li><li>出处：Woodford, <em>Interest and Prices</em>；Clarida, Galí and Gertler, <em>JEL</em> 1999。</li></ul>',11))])}const b=n(s,[["render",m]]);export{h as __pageData,b as default};
